arguments.command:
python3 -I -c 'import json,sys,collections,os
for p in sys.argv[1:]:
 rows=[json.loads(x) for x in open(p)]
 print("\nFILE",p,"N",len(rows),"KEYS",list(rows[0]))
 for i,r in enumerate(rows[:3]):
  print("ROW",i)
  for k,v in r.items():
   if isinstance(v,str): print(k,"len",len(v),"BEGIN",repr(v[:700]),"END",repr(v[-700:]))
   else: print(k,repr(v)[:1500])' ./outputs/grpo/rollouts/1.jsonl ./outputs/grpo/rollouts/2.jsonl ./outputs/grpo/rollouts/3.jsonl

